using audit.Objects;
using Cmf.CLI.Core.Attributes;
using Cmf.CLI.Core.Enums;
using Cmf.CLI.Utilities;
using Cmf.CLI.Core.Objects;
using Microsoft.Extensions.DependencyInjection;
using System.CommandLine;
using System.CommandLine.NamingConventionBinder;
using System.IO.Abstractions;

namespace Cmf.Cli.Plugin.Audit.Commands.install
{
    /// <summary>
    /// "pipeline" command under "review-remote-github": downloads the project from GitHub, then compares its
    /// committed pipelines against the ones generated by cmf pipeline.
    /// </summary>
    [CmfCommand("pipeline", Parent = "review-remote-github", Description = "Will audit the project Pipeline, downloading the project from GitHub")]
    public class PipelineAuditorRemoteGitHub : PipelineAuditor
    {
        #region Public Constructors

        public PipelineAuditorRemoteGitHub() : this(new FileSystem())
        {
        }

        public PipelineAuditorRemoteGitHub(IFileSystem fileSystem, GitHubClient gitHubClient = null) : base(fileSystem)
        {
            this.gitHubClient = gitHubClient;
        }

        private readonly GitHubClient gitHubClient;

        #endregion Public Constructors

        #region Public Methods

        /// <summary>
        /// Configure command
        /// </summary>
        /// <param name="cmd"></param>
        public override void Configure(Command cmd)
        {
            var defaultOptions = AzureDevOpsOptions.GetDefaultValues();

            AuditCommandOptions.AddGitHubOptions(cmd);

            // the generated pipelines embed an Azure DevOps repository URL, so it has to match the committed ones
            cmd.AddOption(new Option<string>(
                aliases: new string[] { "--azureDevOpsUrl" },
                description: "The URI of the Azure DevOps organization, baked into the generated pipeline's repository URL. predefined variable: System.TeamFoundationCollectionUri",
                getDefaultValue: () => defaultOptions.azureDevOpsUrl
                ));

            cmd.AddOption(new Option<string>(
                aliases: new string[] { "--azureDevOpsRepository" },
                description: "The Azure DevOps repository name, baked into the generated pipeline's repository URL. Defaults to the project name",
                getDefaultValue: () => defaultOptions.repository
                ));

            cmd.AddOption(new Option<string>(
                aliases: new string[] { "--infrastructureFileName" },
                description: "Infrastructure file name",
                getDefaultValue: () => ".pipeline-config.json"
                ));

            cmd.AddOption(new Option<string>(
                aliases: new string[] { "--pipelineVersion" },
                description: "cmf pipeline version to use",
                getDefaultValue: () => "latest"
                ));

            cmd.AddOption(new Option<string>(
                aliases: new string[] { "--npmRegistry" },
                description: "npm registry version to use",
                getDefaultValue: () => "https://criticalmanufacturing.io/repository/npm/"
                ));

            cmd.AddOption(new Option<bool>(
                aliases: new string[] { "--generateReport" },
                description: "Will generate a report and persist the flagged artifacts",
                getDefaultValue: () => true
                ));

            cmd.AddOption(new Option<string>(
                aliases: new string[] { "--reportOutputFolder" },
                description: "Folder where a report will be generated, requires the generateReport flag to be true",
                getDefaultValue: () => Path.GetTempPath()
                ));

            // Add the handler
            cmd.Handler = CommandHandler.Create<
                string, string, string, string, string,
                string, string,
                string, string, string,
                bool, string>(ExecuteAsync);
        }

        /// <summary>
        /// Executes the specified target
        /// </summary>
        /// <exception cref="PluginException"></exception>
        public async Task ExecuteAsync(
            string repository, string gitRef, string project, string path, string githubToken,
            string azureDevOpsUrl, string azureDevOpsRepository,
            string infrastructureFileName, string pipelineVersion, string npmRegistry,
            bool generateReport, string reportOutputFolder)
        {
            using var activity = CLI.Core.Objects.ExecutionContext.ServiceProvider?.GetService<ITelemetryService>()?.StartExtendedActivity(this.GetType().Name);

            var folder = GitHubClient.ResolveProjectPath(path, project);
            var workingDir = await (this.gitHubClient ?? new GitHubClient(this.fileSystem)).DownloadFolderAsync(repository, gitRef, folder, githubToken);

            await ExecuteAsync(workingDir, azureDevOpsUrl, azureDevOpsRepository ?? folder.Split('/').Last(), infrastructureFileName, pipelineVersion, npmRegistry, generateReport, reportOutputFolder);
        }

        #endregion Public Methods
    }
}
